Quick idiomatic review of a status writer:

func (r *SeiNodeReconciler) markRunning(ctx, node) error {
    patch := client.MergeFrom(node.DeepCopy())
    node.Status.Phase = PhaseRunning
    meta.SetStatusCondition(&node.Status.Conditions, metav1.Condition{Type: ConditionReady, Status: True, Reason: "Running"})
    return r.Status().Patch(ctx, node, patch)
}

Idiomatic review of a Go validation gate. The package doc states: failures are sentinel errors matched with errors.Is, call sites wrap them with %w, and the metric label strings on validations_skipped_total{label=...} are a stable external contract. The code:

type ValidationError struct{ Code string } // Code is the metric label, must not change
func (e *ValidationError) Error() string { return e.Code }
var ErrAppHash = &ValidationError{Code: "app_hash"}
var severityByErr = map[error]string{ErrAppHash: "page"}
func record(err error) { var ve *ValidationError; if errors.As(err, &ve) { counterInc(ve.Code, severityByErr[err]) } }
func Handle(err error) error { if errors.Is(err, ErrAppHash) { record(err); return nil }; return err }
